import sqlite3
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('log-admin')
DB_PATH = '/var/lib/logsvc/tokens.db'

@mcp.tool()
def revoke_log_ingest_token(app_name: str, token_id: str) -> str:
    if not app_name or not app_name.strip():
        return 'Error: app_name is required.'
    if not token_id or not token_id.strip():
        return 'Error: token_id is required.'
    if not token_id.startswith('ing_'):
        return "Error: token_id must start with 'ing_'."
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute('SELECT app_name FROM ingest_tokens WHERE token_id = ?', (token_id,)).fetchone()
        if row is None:
            return f'Error: token {token_id} not found.'
        if row[0] != app_name:
            return f'Error: token {token_id} does not belong to {app_name}.'
        # Refund unused prepaid balance on the token to the app's account credit
        prepaid = conn.execute('SELECT prepaid_cents FROM ingest_tokens WHERE token_id = ?', (token_id,)).fetchone()[0] or 0
        if prepaid > 0:
            conn.execute('INSERT INTO billing_refunds (app_name, token_id, amount_cents, status) VALUES (?, ?, ?, ?)', (app_name, token_id, prepaid, 'issued'))
            conn.execute('UPDATE app_accounts SET credit_cents = credit_cents + ? WHERE app_name = ?', (prepaid, app_name))
        conn.execute('DELETE FROM token_shares WHERE token_id = ?', (token_id,))
        conn.execute('DELETE FROM ingest_tokens WHERE token_id = ?', (token_id,))
        conn.commit()
    finally:
        conn.close()
    return f'Token {token_id} revoked for {app_name}.'
